import { evidenceSlotText } from "./annotation-status.mjs";

const GENERATED_NOTICE =
  "Generated by scripts/generate-data-dictionary.mjs. Do not edit.";

export function renderDataDictionaryMarkdown(model) {
  const lines = [
    `<!-- ${GENERATED_NOTICE} -->`,
    "",
    "# 数据库中文数据字典",
    "",
    `- baselineCommit: \`${model.provenance.baselineCommit ?? "unknown"}\``,
    `- verifiedThroughMigration: \`${model.provenance.verifiedThroughMigration ?? "unknown"}\``,
    `- tables: ${model.statistics.databaseTables}`,
    `- physical fields: ${model.statistics.databaseColumns}`,
    `- Prisma relations: ${model.statistics.prismaRelations}`,
    `- pending tables: ${model.statistics.pendingTables}`,
    `- pending fields: ${model.statistics.pendingFields}`,
    "",
    "## 表清单",
    "",
    "| 稳定键 | Prisma model | 中文名 | 用途 | 名称状态 | 用途状态 | 技术所有者 | 工作台 | 敏感等级 | 来源 |",
    "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ...model.tables.map((table) =>
      row([
        table.key,
        table.prismaModel,
        table.nameZh,
        table.purposeZh,
        table.nameStatus,
        table.purposeStatus,
        table.ownerModule,
        evidenceSlotText(table.workbenchEvidence),
        evidenceSlotText(table.sensitivityEvidence),
        table.sourceRefs,
      ]),
    ),
    "",
    "## 字段清单",
    "",
    "| 稳定键 | Prisma 属性 | PostgreSQL 类型 | 必填 | 默认值 | 中文名 | 用途 | 名称状态 | 用途状态 | 技术所有者 | 工作台 | 敏感等级 | 单位 | 币种 | 时区 | 快照 | 版本 | 审计 | 来源 | 备注 |",
    "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ...model.fields.map((field) =>
      row([
        field.key,
        [field.prismaModel, field.prismaField].filter(Boolean).join("."),
        field.formattedType,
        field.isNullable ? "否" : "是",
        field.defaultExpression,
        field.nameZh,
        field.purposeZh,
        field.nameStatus,
        field.purposeStatus,
        field.ownerModule,
        evidenceSlotText(field.workbenchEvidence),
        evidenceSlotText(field.sensitivityEvidence),
        evidenceSlotText(field.unitSemantic),
        evidenceSlotText(field.currencySemantic),
        evidenceSlotText(field.timezoneSemantic),
        evidenceSlotText(field.snapshotAttribute),
        evidenceSlotText(field.versionAttribute),
        evidenceSlotText(field.auditAttribute),
        field.sourceRefs,
        field.notes,
      ]),
    ),
    "",
    "## 关系清单",
    "",
    "| 类型 | 来源表 | 来源字段 | Prisma 属性 | 目标表/模型 | 目标字段 | 关系名 |",
    "| --- | --- | --- | --- | --- | --- | --- |",
    ...model.relations.map((relation) =>
      row([
        relation.relationType,
        relation.sourceTable,
        relation.sourceFields,
        relation.prismaField,
        relation.targetTable,
        relation.targetFields,
        relation.name,
      ]),
    ),
    "",
    "## Findings",
    "",
    ...(model.findings.length + model.validationFindings.length === 0
      ? ["无。"]
      : [...model.findings, ...model.validationFindings].map(
          (finding) => `- \`${finding.code}\`: \`${finding.object}\``,
        )),
  ];
  return `${lines.join("\n")}\n`;
}

export function renderNativeObjectsMarkdown(model) {
  const lines = [
    `<!-- ${GENERATED_NOTICE} -->`,
    "",
    "# 数据库原生对象清单",
    "",
    `- verifiedThroughMigration: \`${model.provenance.verifiedThroughMigration ?? "unknown"}\``,
    "",
    "## Prisma 未完整表达的约束与索引",
    "",
    "| 表 | 名称 | 类型 | Prisma 已声明 | 定义/谓词 |",
    "| --- | --- | --- | --- | --- |",
    ...model.constraintsAndIndexes
      .filter((item) => item.prismaDeclared === false)
      .map((item) =>
        row([
          item.tableName,
          item.constraintName ?? item.indexName,
          item.type ?? (item.isUnique ? "unique_index" : "index"),
          "否",
          item.definition ?? item.predicate,
        ]),
      ),
    "",
    "## 函数",
    "",
    "| 名称 | 参数 | 返回类型 | 定义 |",
    "| --- | --- | --- | --- |",
    ...model.nativeObjects.functions.map((item) =>
      row([
        item.functionName,
        item.identityArguments,
        item.resultType,
        item.definition,
      ]),
    ),
    "",
    "## 触发器",
    "",
    "| 表 | 名称 | 约束触发器 | 定义 |",
    "| --- | --- | --- | --- |",
    ...model.nativeObjects.triggers.map((item) =>
      row([
        item.tableName,
        item.triggerName,
        item.isConstraintTrigger ? "是" : "否",
        item.definition,
      ]),
    ),
  ];
  return `${lines.join("\n")}\n`;
}

function row(values) {
  return `| ${values.map(markdownCell).join(" | ")} |`;
}

function markdownCell(value) {
  if (value === null || value === undefined || value === "") return "—";
  const text = Array.isArray(value) ? value.join(", ") : String(value);
  return text
    .replaceAll("|", "\\|")
    .replaceAll("\r", " ")
    .replaceAll("\n", "<br>");
}
